use verus::pervasive::*;

/// Determines whether slice `s` contains the value `val`.
/// Returns true iff there exists some index `i` in bounds of `s` such that s[i] == val,
/// otherwise returns false.
fn slice_contains(s: &[i32], val: i32) -> bool {
    requires(true);
    ensures(|res: bool| {
        // correctness spec: res ↔ ∃i in s.bounds: s[i] == val
        res == exists(|i: int| 0 <= i && i < (s.len() as int) && s[i as usize] == val)
    });

    // Implementation: iterate over s, return true if val found, else false.
    let mut i: usize = 0;
    while i < s.len() {
        invariant(0 <= i && i <= s.len());
        decreases(s.len() - i);
        if s[i] == val {
            return true;
        }
        i += 1;
    }
    false
}

/// Determines whether slices `a` and `b` share at least one common element.
/// Returns true iff there exists indices i in a, j in b with a[i] == b[j].
/// Returns false otherwise (including if either slice is empty).
fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    requires(true);
    ensures(|res: bool| {
        // correctness spec:
        // res ↔ ∃i,j in bounds: a[i] == b[j]
        res == exists(|i: int, j: int| 
            0 <= i && i < (a.len() as int) &&
            0 <= j && j < (b.len() as int) &&
            a[i as usize] == b[j as usize]
        )
    });

    // Iterate over a; for each element a[i], check if b contains a[i] using slice_contains.
    let mut i: usize = 0;
    while i < a.len() {
        invariant(0 <= i && i <= a.len());
        decreases(a.len() - i);

        if slice_contains(b, a[i]) {
            return true;
        }
        i += 1;
    }
    false
}